sources.fontoxpath:
map { "catalog": array { for $b in $doc?store?book?*
          return map { "id": ($b?isbn, $b?title)[1],
                       "label": concat($b?title, " by ", $b?author),
                       "pricing": map { "list": $b?price,
                                        "discounted": $b?price * 0.9 } } },
        "bike": map { "color": $doc?store?bicycle?color } }

